function sv5_create_report(array$u,array$c,array$snap,string$format,string$type):array{
    $pdo=db();$pdo->beginTransaction();$file=null;
    try{
        $q=$pdo->prepare('SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? FOR UPDATE');$q->execute([$snap['id'],$c['id']]);$locked=$q->fetch();if(!$locked)throw new RuntimeException('RESULT_NOT_FOUND');
        $q=$pdo->prepare('SELECT COALESCE(MAX(ReportVersion),0)+1 version FROM SafetyVote_Reports WHERE ResultSnapshotID=? AND ReportType=?');$rt=$type.'_'.$format;$q->execute([$snap['id'],$rt]);$version=(int)$q->fetch()['version'];$reportId='SV-'.$c['id'].'-'.$snap['id'].'-'.strtoupper($type).'-'.strtoupper($format).'-V'.$version;
        $q=$pdo->prepare("SELECT rr.RankNo rank,COALESCE(NULLIF(ca.DisplayName,''),ca.CandidateNo,o.Label,CONCAT('Row ',rr.id)) label,rr.MetricKey metric,COALESCE(rr.NumericValue,rr.RawCount) value,rr.ResultState state FROM SafetyVote_ResultRows rr LEFT JOIN SafetyVote_Candidates ca ON ca.id=rr.CandidateID LEFT JOIN SafetyVote_Options o ON o.id=COALESCE(rr.OptionID,ca.OptionID) WHERE rr.ResultSnapshotID=? ORDER BY rr.RankNo,rr.id");$q->execute([$snap['id']]);$rows=$q->fetchAll();
        $q=$pdo->prepare("SELECT COUNT(*) total FROM SafetyVote_Certifications WHERE ResultSnapshotID=? AND Decision='certified' AND RevokedAt IS NULL");$q->execute([$snap['id']]);$cert=(int)$q->fetch()['total'];$eligibility=sv5_eligibility_history((int)$c['CurrentVersionID'],$pdo);$generated=(new DateTimeImmutable())->format('Y-m-d\TH:i:s.000\Z');
        $built=sv5_report_model(['reportId'=>$reportId,'reportType'=>$type,'campaignCode'=>$c['CampaignCode'],'title'=>$c['TitleTh'],'campaignType'=>$c['CampaignType'],'privacyMode'=>$c['PrivacyMode'],'resultHash'=>$locked['ResultHash'],'snapshotNo'=>$locked['SnapshotNo'],'snapshotStatus'=>$locked['Status'],'quorum'=>$locked['QuorumState'],'tie'=>$locked['TieState'],'reconciliation'=>$locked['ReconciliationState'],'certificationCount'=>$cert,'generatedBy'=>sv_actor($u),'eligible'=>$locked['EligibleCount'],'participation'=>$locked['ParticipationCount'],'accepted'=>$locked['AcceptedBallotCount'],'rejected'=>$locked['RejectedBallotCount'],'abstain'=>$locked['AbstainCount'],'generatedAt'=>$generated,'rows'=>$rows,'eligibility'=>$eligibility]);
        $content=$format==='pdf'?sv5_pdf_v2($built['model']):sv5_xlsx_v2($built['model']);$mime=$format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';$stored=$reportId.'-'.bin2hex(random_bytes(8)).'.'.($format==='pdf'?'pdf':'xlsx');$file=sv5_report_dir().DIRECTORY_SEPARATOR.$stored;file_put_contents($file,$content);$sha=hash('sha256',$content);
        $q=$pdo->prepare('INSERT INTO SafetyVote_Reports(ResultSnapshotID,ReportType,ReportID,ReportVersion,StoredName,MimeType,FileSize,ContentSha256,ResultHashSnapshot,GeneratedBy) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$snap['id'],$rt,$reportId,$version,$stored,$mime,strlen($content),$sha,$locked['ResultHash'],sv_actor($u)]);$id=(int)$pdo->lastInsertId();$pdo->commit();
        return['id'=>$id,'reportId'=>$reportId,'format'=>$format,'mimeType'=>$mime,'fileSize'=>strlen($content),'contentSha256'=>$sha,'resultHash'=>$locked['ResultHash'],'modelHash'=>$built['modelHash'],'documentStatus'=>$built['model']['documentStatus'],'classification'=>$built['model']['classification'],'eligibilityEvolution'=>$built['model']['eligibilityEvolution']];
    }catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();if($file&&is_file($file))@unlink($file);throw$e;}
}
